"""Auto-generated round-trip probes for inverse function pairs."""

from __future__ import annotations

import ast
from pathlib import Path

from bug_vet import ledger as ledger_mod
from bug_vet.paths import ensure_run

INVERSE_WORDS = (
    ("encode", "decode"),
    ("compress", "decompress"),
    ("dump", "load"),
    ("serialize", "deserialize"),
    ("pack", "unpack"),
    ("fold", "unfold"),
    ("collapse", "expand"),
    ("to_dict", "from_dict"),
    ("to_json", "from_json"),
)

AUTO_INPUTS_SOURCE = r'''import json

# Inputs designed so encoding/compression pairs actually transform data.
INPUTS = [
    "",
    "a",
    "x\n" * 60,
    ("line\n" * 40).strip(),
    ("a\nb\nc\n" * 12).strip(),
    "a\nb\na\nb\n" * 10,
    json.dumps({"a": 1, "b": [1, 2, 3], "c": {"d": "e"}}),
    json.dumps([{"id": i % 3, "v": "same"} for i in range(40)]),
    json.dumps({"rows": [{"id": i, "v": "x"} for i in range(40)]}),
    json.dumps([{"k": "中文 😀", "v": None}] * 30, ensure_ascii=False),
    "  padded  \n\nblank\n",
]
'''


def _required_positional(node: ast.FunctionDef | ast.AsyncFunctionDef) -> int:
    args = node.args
    positional = list(args.posonlyargs) + list(args.args)
    required = len(positional) - len(args.defaults)
    return max(0, required)


def find_inverse_pairs(source: str) -> list[tuple[str, str]]:
    """Return sorted ``(forward, backward)`` pairs whose names spell an inverse contract."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    candidates: dict[str, int] = {}
    for node in tree.body:
        if isinstance(node, ast.FunctionDef | ast.AsyncFunctionDef) and not node.name.startswith("_"):
            if _required_positional(node) == 1:
                candidates[node.name] = node.lineno
    pairs: list[tuple[str, str]] = []
    for first, second in INVERSE_WORDS:
        for name in list(candidates):
            if not name.startswith(first):
                continue
            twin = second + name[len(first) :]
            if twin in candidates:
                pairs.append((name, twin))
    return sorted(set(pairs))


def _render_probe(module: str, pairs: list[tuple[str, str]], obligation_id: str) -> str:
    return (
        f'"""Auto-generated round-trip probe for {module} ({len(pairs)} pair(s)).\n\n'
        'Detected from inverse function names; generated by `bug-vet`."""\n\n'
        "from __future__ import annotations\n\n"
        f"import {module} as _m\n\n"
        f'OBLIGATION = "{obligation_id}"\n\n'
        f"{AUTO_INPUTS_SOURCE}\n"
        f"PAIRS = {pairs!r}\n\n\n"
        "def _roundtrip_matches(original: object, restored: object) -> bool:\n"
        "    return restored == original\n\n\n"
        "def self_check() -> list[str]:\n"
        '    """Verify the round-trip checker detects both equality and loss."""\n'
        "    problems: list[str] = []\n"
        '    if not _roundtrip_matches({"k": [1, 2]}, {"k": [1, 2]}):\n'
        '        problems.append("checker rejected identical values")\n'
        '    if _roundtrip_matches("123", 123):\n'
        '        problems.append("checker accepted type-changed restoration")\n'
        "    return problems\n\n\n"
        "def main() -> int:\n"
        "    problems = self_check()\n"
        "    if problems:\n"
        '        print("CHECKER BUG: " + "; ".join(problems))\n'
        "        return 3\n"
        "    failures = []\n"
        "    exercised = 0\n"
        "    for forward_name, backward_name in PAIRS:\n"
        "        forward = getattr(_m, forward_name, None)\n"
        "        backward = getattr(_m, backward_name, None)\n"
        "        if forward is None or backward is None:\n"
        "            continue\n"
        "        for value in INPUTS:\n"
        "            try:\n"
        "                middle = forward(value)\n"
        "                if middle == value:\n"
        "                    continue\n"
        "                exercised += 1\n"
        "                restored = backward(middle)\n"
        "            except Exception:\n"
        "                continue\n"
        "            if not _roundtrip_matches(value, restored):\n"
        "                failures.append(\n"
        '                    f"{forward_name}->{backward_name} did not restore the input: "\n'
        '                    f"{value[:80]!r}"\n'
        "                )\n"
        "                break\n"
        "    if failures:\n"
        '        print("FAIL (" + str(len(failures)) + " pair(s))")\n'
        "        for failure in failures:\n"
        '            print(" -", failure)\n'
        "        return 1\n"
        "    if exercised == 0:\n"
        '        print("INCONCLUSIVE: no pair changed any input")\n'
        "        return 2\n"
        '    print(f"PASS: {len(PAIRS)} pair(s), {exercised} round-trip(s) restored the input")\n'
        "    return 0\n\n\n"
        'if __name__ == "__main__":\n'
        "    raise SystemExit(main())\n"
    )


def generate_roundtrip_probes(
    run_name: str,
    package_path: str | Path,
    *,
    import_root: str | Path | None = None,
    runs_dir: str | Path | None = None,
    register_obligations: bool = True,
) -> dict:
    """Scaffold self-checked round-trip probes for inverse pairs in ``package_path``."""
    root = Path(package_path).resolve()
    if not root.is_dir():
        raise NotADirectoryError(f"{root} is not a directory")
    imp_root = Path(import_root).resolve() if import_root else root.parent
    run_path = ensure_run(run_name, runs_dir=runs_dir)

    generated: list[dict] = []
    skipped = {".git", ".venv", "node_modules", ".bug-vet"}
    for file in sorted(root.rglob("*.py")):
        if skipped & set(file.parts):
            continue
        if "test" in file.name:
            continue
        pairs = find_inverse_pairs(file.read_text(encoding="utf-8", errors="replace"))
        if not pairs:
            continue
        try:
            module = file.relative_to(imp_root).with_suffix("").as_posix().replace("/", ".")
        except ValueError:
            continue
        if module.endswith(".__init__"):
            module = module[: -len(".__init__")]

        slug = ledger_mod.digest(module)[:8]
        claim_id = f"rt-{slug}"
        ob_id = ledger_mod.obligation_id(claim_id)
        if register_obligations:
            pair_labels = ", ".join(f"{f}/{b}" for f, b in pairs)
            ledger_mod.add_obligation(
                run_path,
                {
                    "id": claim_id,
                    "origin": "oracle:roundtrip",
                    "kind": "roundtrip",
                    "text": f"Inverse pair(s) in {module} preserve input on round-trip: {pair_labels}",
                    "source": str(file),
                    "line": 1,
                    "symbol": pairs[0][0],
                    "visibility": "public",
                },
            )

        probe_name = f"auto_roundtrip_{file.stem}_{slug}.py"
        probe_path = run_path / "probes" / probe_name
        probe_path.write_text(_render_probe(module, pairs, ob_id), encoding="utf-8")
        generated.append(
            {
                "probe": probe_name,
                "probe_path": str(probe_path),
                "module": module,
                "pairs": pairs,
                "obligation_id": ob_id,
            }
        )

    return {"run": run_name, "count": len(generated), "generated": generated}
